<script lang="ts">
import {onMount,tick} from 'svelte';
import {api,type Book,type Copy,type Shelf,type Draft} from '../../lib/api';
import BookDelete from './BookDelete.svelte';
import FirstPublicationEditor from './FirstPublicationEditor.svelte';
import BookForm from './BookForm.svelte';import CopyArchive from './CopyArchive.svelte';
export let bookId:number;
type Borrower={id:number;name:string;notes:string};type Loan={id:number;copy_id:number;borrower:string;checked_out_at:string;due_date:string|null;returned_at:string|null};
let book:Book|null=null;let shelves:Shelf[]=[];let borrowers:Borrower[]=[];let loans:Loan[]=[];let loading=true;let busy=false;let error='';let message='';let editing=false;let editingBook:Book|null=null;let editingDraft:Draft|null=null;let addShelf='';let selected:Record<number,string>={};let due:Record<number,string>={};let names:Record<number,string>={};let adding:Record<number,boolean>={};let loadSequence=0;
const keys=new Map<string,string>();function requestKey(payload:string){if(!keys.has(payload))keys.set(payload,crypto.randomUUID());return keys.get(payload)!;}
async function load(){const sequence=++loadSequence;try{const result=await Promise.all([api<Book>(`/api/books/${bookId}`),api<Shelf[]>('/api/shelves'),api<Borrower[]>('/api/borrowers'),api<Loan[]>(`/api/books/${bookId}/loans`)]);if(sequence===loadSequence){[book,shelves,borrowers,loans]=result;}}catch(e){if(sequence===loadSequence)error=(e as Error).message;}finally{if(sequence===loadSequence)loading=false;}}
onMount(()=>{load();const refresh=(event:Event)=>{if(event instanceof CustomEvent&&event.detail?.source==='workspace')return;load();};const edit=(event:Event)=>{if((event as CustomEvent<number>).detail===bookId&&!busy&&book){editing=!editing;if(editing){editingBook=book;editingDraft={...book,authors:[...book.authors]};}window.dispatchEvent(new CustomEvent('library-book-editor-changed',{detail:{bookId,open:editing}}));}};window.addEventListener('focus',refresh);window.addEventListener('library-inventory-changed',refresh);window.addEventListener('library-edit-book-details',edit);return()=>{loadSequence++;window.removeEventListener('focus',refresh);window.removeEventListener('library-inventory-changed',refresh);window.removeEventListener('library-edit-book-details',edit);};});
function shelfLabel(shelf:Shelf){const place=shelf.bookcase.trim().toLocaleLowerCase().replace(/\s+(?:bookshelf|bookcase|shelf|cabinet)$/,'');return place===shelf.name.trim().toLocaleLowerCase()?shelf.bookcase:`${shelf.bookcase} / ${shelf.name}`;}
function active(copyId:number){return loans.find(loan=>loan.copy_id===copyId&&!loan.returned_at);}
async function move(copy:Copy,event:Event){if(busy)return;busy=true;error='';let saved=false;const source=event.target as HTMLElement;try{const value=(event.target as HTMLSelectElement).value;await api(`/api/copies/${copy.id}`,{shelf_id:value?Number(value):null,revision:copy.revision},'PATCH');message='Shelf updated.';saved=true;}catch(e){error=(e as Error).message;}finally{await load();busy=false;await tick();if(saved&&!error)window.dispatchEvent(new CustomEvent('library-shelf-saved',{detail:{source}}));}}
async function mutate(url:string,body:Record<string,unknown>,success:string){if(busy)return false;busy=true;error='';const payload=JSON.stringify([url,body]);try{await api(url,{...body,request_key:requestKey(payload)});keys.delete(payload);await load();message=success;return true;}catch(e){error=(e as Error).message;await load();return false;}finally{busy=false;}}
async function addCopy(){if(await mutate(`/api/books/${bookId}/copies`,{shelf_id:addShelf?Number(addShelf):null},'Another copy added.'))window.dispatchEvent(new CustomEvent('library-inventory-changed',{detail:{source:'workspace',bookId}}));}
async function checkout(copyId:number){if(!selected[copyId])return;if(await mutate('/api/loans',{copy_id:copyId,borrower_id:Number(selected[copyId]),due_date:due[copyId]||''},'Book checked out.'))window.dispatchEvent(new CustomEvent('library-inventory-changed',{detail:{source:'workspace',bookId}}));}
async function returnLoan(id:number){if(await mutate(`/api/loans/${id}/return`,{},'Book returned.'))window.dispatchEvent(new CustomEvent('library-inventory-changed',{detail:{source:'workspace',bookId}}));}
async function addBorrower(copyId:number){const name=(names[copyId]||'').trim();if(!name||busy)return;busy=true;error='';const payload=JSON.stringify(['borrower',name]);try{const result=await api<{id:number}>('/api/borrowers',{name,notes:'',request_key:requestKey(payload)});keys.delete(payload);await load();selected[copyId]=String(result.id);names[copyId]='';adding[copyId]=false;message='Borrower added.';busy=false;await checkout(copyId);}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<section class="workspace" aria-label="Your copies and lending">
{#if error}<p role="alert" class="library-error">{error}</p>{/if}
{#if loading}<p>Loading your copies…</p>{:else if book}
{#if editing&&editingBook&&editingDraft}<section class="workspace_editor" aria-label="Edit book details"><BookForm draft={editingDraft} {shelves} editing={editingBook} saved={()=>window.location.reload()} busyChanged={(value)=>busy=value}/><FirstPublicationEditor book={editingBook}/></section>{/if}
<div class="workspace_heading"><h2>Your copies</h2><span>{book.count} {book.count===1?'copy':'copies'} · {book.available} available</span></div>
{#each book.copies as copy (copy.id)}{@const loan=active(copy.id)}
<article class="workspace_copy" aria-label={copy.label||`Copy ${copy.id}`}>
<div class="workspace_home"><div class="workspace_copy-title"><strong>{copy.label||`Copy ${copy.id}`}</strong><span class:out={copy.out}>{copy.out?'On loan':'Available'}</span></div><label class="library-field">Home shelf<select value={copy.shelf_id||''} disabled={busy} onchange={(event)=>move(copy,event)}><option value="">Unassigned</option>{#each shelves as shelf}<option value={shelf.id} title={`${shelf.bookcase} / ${shelf.name}`}>{shelfLabel(shelf)}</option>{/each}</select></label><CopyArchive {copy}/></div>
<div class="workspace_lend"><h3>{loan?'On loan':'Lend this copy'}</h3>
{#if loan}<p>Lent to <strong>{loan.borrower}</strong></p><p class="workspace_dates">Checked out {loan.checked_out_at.slice(0,10)}{#if loan.due_date} · Due {loan.due_date}{/if}</p><button class="library-button" disabled={busy} onclick={()=>returnLoan(loan.id)}>Return book</button>
{:else if copy.out}<p>On loan. Refresh to load its details.</p>
{:else}
{#if borrowers.length}<div class="workspace_checkout"><label class="library-field">Lend to<select value={selected[copy.id]||''} onchange={(event)=>selected={...selected,[copy.id]:event.currentTarget.value}} disabled={busy}><option value="">Choose a borrower</option>{#each borrowers as borrower}<option value={borrower.id}>{borrower.name}</option>{/each}</select></label><button class="library-button" disabled={busy||!selected[copy.id]} onclick={()=>checkout(copy.id)}>Check out</button></div><button type="button" class="workspace_text-action" disabled={busy} onclick={()=>adding[copy.id]=!adding[copy.id]}>{adding[copy.id]?'Cancel new borrower':'New borrower'}</button>{/if}
{#if !borrowers.length||adding[copy.id]}<form class="workspace_checkout" onsubmit={(event)=>{event.preventDefault();addBorrower(copy.id);}}><label class="library-field">Lend to<input value={names[copy.id]||''} oninput={(event)=>names={...names,[copy.id]:event.currentTarget.value}} maxlength="200" required disabled={busy} placeholder="Borrower’s name"/></label><button class="library-button" disabled={busy||!(names[copy.id]||'').trim()}>Lend book</button></form>{/if}
<details class="workspace_due"><summary>Due date (optional)</summary><label class="library-field">Return by<input type="date" value={due[copy.id]||''} oninput={(event)=>due={...due,[copy.id]:event.currentTarget.value}} disabled={busy}/></label></details>
{/if}
</div></article>
{/each}
<details class="workspace_more"><summary>Add another copy</summary><div class="workspace_add"><label class="library-field">Shelf for another copy<select bind:value={addShelf} disabled={busy}><option value="">Unassigned</option>{#each shelves as shelf}<option value={shelf.id} title={`${shelf.bookcase} / ${shelf.name}`}>{shelfLabel(shelf)}</option>{/each}</select></label><button class="library-button secondary" disabled={busy} onclick={addCopy}>+ Add another copy</button><p>Only add a copy when you own another physical book of this edition.</p></div></details>
{#if loans.some(loan=>loan.returned_at)}<details class="workspace_history"><summary>Loan history</summary><ul>{#each loans.filter(loan=>loan.returned_at) as loan}<li>{loan.borrower} · Lent {loan.checked_out_at.slice(0,10)} · Returned {loan.returned_at?.slice(0,10)}</li>{/each}</ul></details>{/if}
<BookDelete {book} disabled={busy} busyChanged={(value)=>busy=value}/>{/if}<p role="status">{message}</p>
</section>
<style>
@layer components {
.workspace{display:grid;gap:0;border:0;background:transparent;padding:0;color:var(--app-ink,var(--text));min-width:0;}
.workspace_heading{display:flex;justify-content:space-between;align-items:baseline;gap:1rem;padding-bottom:1rem;h2{font-family:var(--app-serif,Georgia,serif);font-size:1.375rem;font-weight:400;}span{font-size:.875rem;color:var(--app-muted,var(--text-2));font-variant-numeric:tabular-nums;}}
.workspace_copy{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:1.5rem;padding:1rem 0;border-top:1px solid var(--app-line,var(--border));}
.workspace_home,.workspace_lend{display:grid;align-content:start;gap:.5rem;min-width:0;}.workspace_home{max-width:28rem;}.workspace_lend h3{font-size:.875rem;font-weight:600;margin-bottom:.25rem;}
.workspace_copy-title{display:flex;align-items:center;justify-content:space-between;gap:.5rem;min-height:1.5rem;margin-bottom:.25rem;strong{font-size:.9375rem;}span{display:inline-flex;align-items:center;gap:.375rem;font-size:.8125rem;color:var(--app-accent,var(--text));}span::before{content:'';width:.375rem;height:.375rem;border-radius:50%;background:currentColor;}span.out{color:var(--app-muted,var(--text-2));}}
.workspace_checkout{display:flex;gap:.5rem;align-items:end;flex-wrap:wrap;label{flex:1;min-width:8rem;}button{min-height:2.75rem;padding-inline:1rem;}}
.workspace_dates,.workspace_due,.workspace_history,.workspace_add p{font-size:.875rem;color:var(--app-muted,var(--text-2));line-height:1.5;}.workspace_due summary,.workspace_history summary{cursor:pointer;min-height:2.75rem;display:flex;align-items:center;}.workspace_due label{margin-top:.375rem;}.workspace_more{font-size:.875rem;border-top:1px solid var(--app-line,var(--border));padding-top:.25rem;summary{cursor:pointer;min-height:2.75rem;display:flex;align-items:center;}}
.workspace_add{display:flex;align-items:end;flex-wrap:wrap;gap:.75rem;padding-top:.5rem;label{max-width:24rem;flex:1;min-width:12rem;}p{flex-basis:100%;margin-bottom:.75rem;}}
.workspace_editor{padding-bottom:1.25rem;margin-bottom:1rem;border-bottom:1px solid var(--app-line,var(--border));}
.workspace_text-action{justify-self:start;min-height:2.75rem;padding:.5rem 0;border:0;background:transparent;color:var(--app-muted,var(--text-2));font-size:.875rem;text-decoration:underline;text-underline-offset:.2em;}
.workspace :global(.archive_wrap .library-button){justify-self:start;min-height:2.75rem;padding:.5rem 0;border:0;border-radius:0;background:transparent;color:var(--app-muted,var(--text-2));font-size:.875rem;text-decoration:underline;text-underline-offset:.2em;}
.workspace :global(.library-field){font-size:.875rem;gap:.375rem;}.workspace :global(input),.workspace :global(select){min-height:2.75rem;border-radius:.125rem;background:var(--app-surface,var(--background));font-size:.875rem;padding:.625rem .75rem;}.workspace :global(.library-button){border-radius:.125rem;font-size:.875rem;}.workspace :global(.library-button:disabled){opacity:1;background:color-mix(in srgb,var(--app-accent) 13%,var(--app-paper));color:color-mix(in srgb,var(--app-accent) 74%,var(--app-paper));border-color:color-mix(in srgb,var(--app-accent) 20%,var(--app-paper));}.workspace :global(.archive_wrap .library-button:disabled){background:transparent;color:var(--app-muted,var(--text-2));border:0;}.workspace_history ul{padding-top:.5rem;display:grid;gap:.5rem;}.workspace > :global(p[role=status]:empty){display:none;}
@media(width<70rem) and (width>=58rem){.workspace_copy{grid-template-columns:minmax(0,1fr);gap:.75rem;}.workspace{padding:0;}.workspace_home{max-width:none;}}
@media(width<40rem){.workspace{padding:0;}.workspace_copy{grid-template-columns:minmax(0,1fr);gap:1rem;}.workspace_heading{align-items:start;flex-direction:column;gap:.25rem;}}
}
</style>
